#!/usr/bin/env python3
"""Generate the final Chinese report from frozen paired tables, without search."""
import csv,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return list(csv.DictReader(p.open()))
def short(x):return 'Bromberger' if x.startswith('2018') else 'SMT_random' if x.startswith('SMT_random') else 'convert' if x.startswith('convert') else x
def mean(rows,key):return statistics.mean(float(r[key]) for r in rows) if rows else 0

def main():
    mech=ROOT/'results/round8_macro/mechanism_400ms';online=ROOT/'results/round8_macro/online_30s';mr=read(mech/'sessions.csv');rs=read(online/'sessions.csv');ag=read(online/'aggregate.csv');pairs=read(online/'pairs.csv');queries=read(online/'broad_queries.csv');decision=json.loads((online/'decision.json').read_text());validation=json.loads((ROOT/'results/round8_dev/validation/validated.json').read_text());audits=[json.loads((p/'AUDIT.json').read_text()) for p in (mech,online)];cases=sorted({r['instance'] for r in rs})
    reach={r['id']:r for r in read(online/'reachability_time_summary.csv')}
    for r in rs:r['known_gap_fraction']=reach[r['id']]['known_gap_fraction']
    text=['# 第八轮宏观生成实现与实验报告','',f"**结论：{decision['conclusion']}。** 本轮在冻结提交 13eea92 上实现并验证了宏观离散选择，实际执行 48 个 0.4 秒机制动作和 18 个 30 秒在线会话，没有重跑 HighDiv、没有新 900 秒实验，也未调优六个评测案例。采样源码冻结在 538ea34；最后结果提交只增加报告、离线补充、附加回归和证据，采样策略未变。",'', '## 实现与正确性','', 'ChoiceCatalog 识别根合取路径下的常量等式备选，保留整个多变量配置；一般 OR 不转为 XOR。MacroChoiceGenerator 查询完整 F 加单个或至多两个备选，变量由原公式协调。单备选无额外限制的 UNSAT 才能缓存；组合冲突、Timeout 和 Unknown 不提升为全局不可达。没有变量块扩张、polish、准备复用或 MaxSMT。', '', '两个在线配置共用原 residual-cardinality 微观模块。每轮上限 1 秒，微观/广泛各最多 40%，至少 20% 留给最终输出；微观正收益也保留 broad 机会。广泛最多两次查询，所有准备、失败、回退、验证与写入计费。轮内覆盖冻结，只有及时写出的最好合法不同模型提交。8 轮无增益触发事件并有界重建，不直接停止。', '', f"Release 和 ASan/UBSan 各通过 {validation['release_cpp']} 项 C++、{validation['release_python']} 项 Python 回归；独立冻结 Manual 审计通过 {sum(a['sessions'] for a in audits)} 个会话/动作、{sum(a['validated_models'] for a in audits)} 次保存模型求值（包含内部候选，非不同正式输出数）。合法性、短路访问、低 64 位、原分母、轮内评分、时戳与提交恒等式均核对。测试和源/二进制 SHA 位于 results/round8_dev/validation。结果复核时另补实际宏观 SAT 零收益与零收益种子产生可达缺口的回归，采样源码和实验二进制 SHA 不变；补充验证见 results/round8_dev/post_audit_validation。",'', '## 0.4 秒冷启动机制对照','', '真实部分为三个开发实例各 prefix 1/10、三个随机种子，两配置共 36 动作；另 12 动作为明确标记的合成实例。双方都把已有种子提交到基态 S′，比较剩余收益。全部初始化/恢复成本计入 0.4 秒动作；这不是常驻模块吞吐率。失败动作收益为 0，仍进入均值/中位数。', '', '|状态类别|配置|动作数|无候选|平均额外 bit|中位额外 bit|平均完整耗时 ms|宏观查询数|', '|---|---|---:|---:|---:|---:|---:|---:|']
    for case in sorted({r['instance'] for r in mr}):
        for mode in ('micro_plain','micro_macro'):
            rows=[r for r in mr if r['instance']==case and r['mode']==mode];text.append(f"|{short(case)}|{mode}|{len(rows)}|{sum(int(r['no_candidate']) for r in rows)}|{mean(rows,'gain'):.3f}|{statistics.median(float(r['gain']) for r in rows):.1f}|{1000*mean(rows,'session_seconds'):.3f}|{sum(int(r['macro_calls']) for r in rows)}|")
    text+=['', '真实开发结构只有 SMT_random 支持当前目录；Bromberger 和 convert 使用普通回退。合成公式证明可以整体切换并协调等式，但普通探索同样能生成合法不同模型，不能以合成 SAT 次数宣称性能优势。逐快照、重复与查询状态见机制目录 sessions / pairs / broad_queries.csv。convert 每动作实际执行了两次普通探索查询，但均未交付候选；两侧平均初始化分别约 211.7 / 262.4 ms，挤占了 400 ms 总预算。不能把这些失败解释为不可达或再次证明局部锁死。','', '## 30 秒从首次模型开始的在线比较','', '每案例三个 seed，同对同公式与种子编号；各自从首次求解开始，不恢复历史前缀。初始合法模型计为样本 1。完整进程耗时包含启动、加载、所有查询、最终日志及析构；收益率使用该完整耗时，不把初始化免费。下表覆盖为 30 秒内实际写完的正式集合。', '', '|实例|plain 平均覆盖 %|macro 平均覆盖 %|差值 pp|配对胜/平/负|差值中位 pp|', '|---|---:|---:|---:|---|---:|']
    for case in cases:
        x=[r for r in rs if r['instance']==case and r['mode']=='micro_plain'];y=[r for r in rs if r['instance']==case and r['mode']=='micro_macro'];a=next(r for r in ag if r['instance']==case and r['axis']=='time' and float(r['level'])==30)
        text.append(f"|{short(case)}|{mean(x,'final_percent'):.4f}|{mean(y,'final_percent'):.4f}|{float(a['mean_delta_pp']):+.4f}|{a['wins']}/{a['ties']}/{a['losses']}|{float(a['median_delta_pp']):+.4f}|")
    text+=['', '|实例|共同前缀|共同配对数/3|平均差 pp|中位差 pp|胜/平/负|','|---|---:|---:|---:|---:|---|']
    for case in cases:
        for k in (2,5,10,20,50):
            a=next(r for r in ag if r['instance']==case and r['axis']=='prefix' and int(float(r['level']))==k)
            text.append(f"|{short(case)}|{k}|{a['common_pairs']}/3|{format(float(a['mean_delta_pp']),'+.4f') if a['mean_delta_pp'] else '未共同完成'}|{format(float(a['median_delta_pp']),'+.4f') if a['median_delta_pp'] else '未共同完成'}|{a['wins']}/{a['ties']}/{a['losses']}|")
    text+=['', '固定 1/2/5/10/20/30 秒的全部逐例配对保存在 checkpoints.csv / pairs.csv / aggregate.csv；未完成前缀留空，没有用短前缀冒充完成，也未删除无输出与零收益。每个会话为统计单元，轮次不是独立重复。只有三个种子，均值与配对胜负是描述结果，不作总体显著性主张。','', '## 高原、恢复与新增成本','', '|实例|配置|平均最长零收益样本段|平均最长无增长秒|已知可达缺口时间占比|停滞后恢复次数|恢复 bit 合计|宏观正式 bit 合计|', '|---|---|---:|---:|---:|---:|---:|---:|']
    for case in cases:
        for mode in ('micro_plain','micro_macro'):
            rows=[r for r in rs if r['instance']==case and r['mode']==mode];text.append(f"|{short(case)}|{mode}|{mean(rows,'longest_zero_run'):.1f}|{mean(rows,'longest_no_growth'):.3f}|{100*mean(rows,'known_gap_fraction'):.2f}%|{sum(int(r['recoveries']) for r in rows)}|{sum(int(r['recovery_gain']) for r in rows)}|{sum(int(r['macro_formal_gain']) for r in rows)}|")
    text+=['', '已知可达缺口来自冻结历史模型池的事后见证；未找到见证仅为 REACHABILITY_UNKNOWN，末段为右删失。本表时间比例采用补充的逐输出事件口径：即使 covered 不增，完整 seen0/seen1 也可能改变，须在该时刻更新可达缺口判定。原按高原起点的判定和所有原得分仍保留在 sessions.csv / plateau_segments.csv，新时间比例在 reachability_time_summary.csv，逐区间及见证在 reachability_intervals.csv。线上从不使用池。新轮次实际模式由原变量满足的全部备选重算，plain 的结构诊断在运行结束后离线完成，其成本不伪装成在线成本。每段见证、零收益/无输出区分和删失位于 plateau_segments.csv；内部失败/重复与模块耗时在原 plateau.json、rounds.jsonl，停滞处理与恢复见 events.jsonl。','', '|实例|配置|平均初始化 ms|平均微观秒|平均广泛秒|平均完整进程秒|平均新增 bit/完整秒|正式样本合计|', '|---|---|---:|---:|---:|---:|---:|---:|']
    for case in cases:
        for mode in ('micro_plain','micro_macro'):
            rows=[r for r in rs if r['instance']==case and r['mode']==mode];text.append(f"|{short(case)}|{mode}|{1000*mean(rows,'initialization_seconds'):.2f}|{mean(rows,'micro_seconds'):.3f}|{mean(rows,'broad_seconds'):.3f}|{mean(rows,'session_seconds'):.3f}|{mean(rows,'gain_per_complete_second'):.2f}|{sum(int(r['formal_count']) for r in rows)}|")
    macro=[q for q in queries if q['origin']=='macro_choice'];text+=['',f"在线宏观查询共 {len(macro)} 次，状态计数："+str(dict(__import__('collections').Counter(q['status'] for q in macro)))+'。逐次记录目标组、强制改变的不同变量数、实际模式变化、候选全覆盖收益及动作完整成本。模式变而收益为零保留；SAT 但去重拒绝不算输出。来源只是实际生成路径，不把前序增量求解历史的影响强行作独立因果归因。', '', f"实际进程超过名义时限的最大额外墙钟 {max(float(r['overrun']) for r in rs):.6f} 秒。所有时间阈值覆盖仍只取及时正式输出；清理/日志和不可中断超额成本仍进入完整耗时。内部保留的及时见证若未在正式截止前写出，不倒签为正式输出。",'', '## 解释边界与逐例失败原因', '', '9 对独立首次求解实际给出了相同初始模型，已逐对比较赋值哈希，仍分别承担实际获取成本。18 会话使用 15 槽动态队列，同一配对并不保证相同瞬时系统负载：convert seed 1 的 macro 于 08:47:12 UTC 启动，plain 于 08:47:42 UTC 启动，跨了两个波次。没有因此重跑或校准并发。Bromberger / convert 目录为空，两侧广泛路径实际都是普通探索；它们的差异包含初始化、增量求解历史和截止时机，不能把下降直接作离散选择机制的独立因果效应，也不能未经控制称为随机噪声。', '', 'SMT_random 每会话只输出了初始模型，随后没有新正式模型，不是持续输出大量不同零收益模型。初始求解约用去 12 秒；提交初始模型后的剩余时间有历史合法模型能增加覆盖，补充时间比例约为 plain 60.79% / macro 59.82%（分母为全 30 秒）。在真正适用的结构上，101 次宏观查询未找到一个可交付模型，这比“变量/模式变了多少”更直接地支持本批没有收益。', '', '宏观配置总停滞恢复 bit 较多，却全部来自共同微观/回退路径，并非宏观选择；落后更多时也可能留下更多可恢复缺口。convert 的 macro 正式模型合计 91 个，高于 plain 的 85 个，最终覆盖却较低，不能将模型数或恢复总量单独当作进步。', '', '## 四个问题的回答','', '1. **HighDiv 早期多覆盖什么？** 在同一实际前 10 前缀比较中，SMT_random 多 6,181 bit，主要来自低中位和算术式；Bromberger 多 4,516 bit（整数变量 +4,194，高位 +2,358）；40-9 多 9,008 bit（算术式 +5,504，高位 +4,687）；convert 多 28,040 bit（算术式 +18,811）。其余五例及第二个模型的精确互补收益见早期报告。高位变化并不都来自符号翻转；不能从模型距离直接推导覆盖。可靠选择与实际短路路径均保存逐模型证据，相关性不当作因果。','', '2. **双方是否有严重高原？** 有。例如 Bromberger 的 HighDiv 最长末段约 887.5 秒、19,489 个不同零收益模型；原 LIA 约 870.4 秒、8,043 个。各算法 SMT_random / SMT_real / convert 等仍可在历史池找到未补齐的实际可达缺口。最终无见证的缺口保持未知，不证明饱和；九例逐段证据和删失状态见高原报告。','', '3. **除了 convert，什么结构限制旧机制？** SMT_random 的 114 个可靠组涉及 191 个变量，35.1% 的组有多变量联动；必要等式还关联更多变量。已有 prefix-1 safe 区域零自由度证据说明方向/LineDomain 无法留在该区域内改变模型。Global bit 查询保留完整 F，并非逻辑上不能跨分支；本轮结果只能揭示限预算的实际求解表现，不把它解释为全局能力不足。SMT_real 与真实 bofill 的结构诊断支持存在类似选择，但未用它们调参或加入本轮性能实验。','', '4. **新宏观候选是否值得成本？** 合成测试确认正确跨配置、协调变量和保留见证；是否更便宜必须看上面的同预算实测。真实开发适用面只有一个案例，普通探索在合成例也能切换；不能把模式数量或唯一出现的模型当作“原方法难以生成”的证明。最终按冻结门槛作以下判断。','', '## 预设判定与交付','', f"达到案例改善条件：{[short(x) for x in decision['improved_cases']]}；明显退步案例：{[short(x) for x in decision['obvious_regressions']]}；宏观停滞恢复贡献 {decision['macro_recovery_gain']} bit。总体恢复对照 {decision['total_recovery']}；完整耗时归一化收益对照 {decision['normalized_gain_rate']}。结论为 **{decision['conclusion']}**，不增加目标包、调用次数或预算挽饰结果。",'', '两套原始证据均有 raw.tar.gz、逐文件 archive.json、plan.json、runs.jsonl、AUDIT.json，原始模型和实际写完收据完整保留；analysis CSV 与中文报告为独立新目录。重放命令、构建与测试环境见 [实现与复现](第八轮实现与复现.md)，冻结预算与晋级条件见 [实验协议](第八轮实验协议.md)。HighDiv 仅为历史 900 秒样本质量参考，不把这次 30 秒实验解释成新的严格 HighDiv 同条件速度比较。']
    (ROOT/'docs/第八轮宏观生成实现与实验报告.md').write_text('\n'.join(text)+'\n')
if __name__=='__main__':main()
